// pluck_hmm.dice, translated by tddlog's scripts/dice2prism.py, component 0 (bool): 5 steps, 4 registers, 7 commands.
// "v1": P=? [F ("done" & x1)]
dtmc

module program
  pc : [0..5] init 0;
  x0 : bool init false;
  x1 : bool init false;
  x2 : [0..63] init 0;
  x3 : bool init false;
  [] pc=0 -> 0.1:(x1'=true)&(x2'=0)&(x3'=true)&(pc'=2) + 0.9:(x1'=true)&(x2'=0)&(x3'=false)&(pc'=3);
  [] pc=1 & x0 -> 0.7:(x0'=false)&(x3'=true)&(pc'=2) + 0.3:(x0'=false)&(x3'=false)&(pc'=3);
  [] pc=1 & !x0 -> 0.1:(x0'=false)&(x3'=true)&(pc'=2) + 0.9:(x0'=false)&(x3'=false)&(pc'=3);
  [] pc=2 -> 0.3:(x0'=x3)&(x2'=mod(x2 + 1, 64))&(x3'=(mod(x2 + 1, 64) < 50))&(pc'=4) + 0.7:(x0'=x3)&(x1'=false)&(x2'=mod(x2 + 1, 64))&(x3'=(mod(x2 + 1, 64) < 50))&(pc'=4);
  [] pc=3 -> 0.6:(x0'=x3)&(x2'=mod(x2 + 1, 64))&(x3'=(mod(x2 + 1, 64) < 50))&(pc'=4) + 0.4:(x0'=x3)&(x1'=false)&(x2'=mod(x2 + 1, 64))&(x3'=(mod(x2 + 1, 64) < 50))&(pc'=4);
  [] pc=4 & x3 -> (x3'=false)&(pc'=1);
  [] pc=4 & !x3 -> (x0'=false)&(x2'=0)&(x3'=false)&(pc'=5);
  [] pc=5 -> true;
endmodule

label "done" = pc=5;

