var input_facts = relationOfFacts(lpFacts['input/1'] || []);
var out_facts = relationOfFacts(lpFacts['out/2'] || []);
var target_facts = relationOfFacts(lpFacts['target/1'] || []);

var in_ = in__facts;

var instances_deleted = [].concat(
  // 0.01::deleted(K) :- in(K,_A1).
  (function() {
    return _.flatten(map(function(e1) {
