          ['inserted', [K, I, 'b'], and([e1.v, e2.v, chosen[1]])],
          ['inserted', [K, I, 'c'], and([e1.v, e2.v, chosen[2]])],
          ['inserted', [K, I, 'd'], and([e1.v, e2.v, chosen[3]])],
