var inserted_by_2_3 = index(inserted, [1, 2]);
// ins/3: recursive; the rules applied in stages from no tuple, each
// reading the stage before, until a stage adds no tuple and the stages number the tuples
var stage_ins = function(rels) {
  var ins = rels[0];
  var ins_by_1_2 = index(ins, [0, 1]);
  var instances_ins = [].concat(
    // ins(K,I,I) :- ends(K,I).
    (function() {
      return _.flatten(map(function(e1) {
        var K = e1.t[0];
        var I = e1.t[1];
        return [['ins', [K, I, I], e1.v]];
      }, _.values(ends)));
    })(),
    // ins(K,I,J) :- out(I,C), \+ ends(K,I), inserted(K,I,C), I1 is I + 1, ins(K,I1,J).
    (function() {
      return _.flatten(map(function(e1) {
        var I = e1.t[0];
        var C = e1.t[1];
        var I1 = (I + 1);
        return _.flatten(map(function(e2) {
          var K = e2.t[0];
          return _.flatten(map(function(e3) {
            var J = e3.t[2];
            return [['ins', [K, I, J], and([e1.v, e2.v, not(holds(ends, [K, I])), e3.v])]];
