var replaced = relation({}, instances_replaced);

var instances_replacement = [].concat(
  // 0.2::replacement(K,a); 0.2::replacement(K,b); 0.2::replacement(K,c); 0.2::replacement(K,d); 0.2::replacement(K,e) :- in(K,_A1).
